   204  #define FTP_LP_MALFORMATED_PERM 0x01000000
   205
   206  static int ftp_pl_get_permission(const char *str)
   207  {
   208    int permissions = 0;
   209    /* USER */
   210    if(str[0] == 'r')
   211      permissions |= 1 << 8;
   212    else if(str[0] != '-')
   213      permissions |= FTP_LP_MALFORMATED_PERM;
   214    if(str[1] == 'w')
   215      permissions |= 1 << 7;
   216    else if(str[1] != '-')
   217      permissions |= FTP_LP_MALFORMATED_PERM;
   218
   219    if(str[2] == 'x')
   220      permissions |= 1 << 6;
   221    else if(str[2] == 's') {
   222      permissions |= 1 << 6;
   223      permissions |= 1 << 11;
   224    }
   225    else if(str[2] == 'S')
   226      permissions |= 1 << 11;
   227    else if(str[2] != '-')
   228      permissions |= FTP_LP_MALFORMATED_PERM;
   229    /* GROUP */
   230    if(str[3] == 'r')
   231      permissions |= 1 << 5;
   232    else if(str[3] != '-')
   233      permissions |= FTP_LP_MALFORMATED_PERM;
   234    if(str[4] == 'w')
   235      permissions |= 1 << 4;
   236    else if(str[4] != '-')
   237      permissions |= FTP_LP_MALFORMATED_PERM;
   238    if(str[5] == 'x')
   239      permissions |= 1 << 3;
   240    else if(str[5] == 's') {
   241      permissions |= 1 << 3;
   242      permissions |= 1 << 10;
   243    }
   244    else if(str[5] == 'S')
   245      permissions |= 1 << 10;
   246    else if(str[5] != '-')
   247      permissions |= FTP_LP_MALFORMATED_PERM;
   248    /* others */
   249    if(str[6] == 'r')
   250      permissions |= 1 << 2;
   251    else if(str[6] != '-')
   252      permissions |= FTP_LP_MALFORMATED_PERM;
   253    if(str[7] == 'w')
   254      permissions |= 1 << 1;
   255    else if(str[7] != '-')
   256        permissions |= FTP_LP_MALFORMATED_PERM;
   257    if(str[8] == 'x')
   258      permissions |= 1;
   259    else if(str[8] == 't') {
   260      permissions |= 1;
   261      permissions |= 1 << 9;
   262    }
   263    else if(str[8] == 'T')
   264      permissions |= 1 << 9;
   265    else if(str[8] != '-')
   266      permissions |= FTP_LP_MALFORMATED_PERM;
   267
   268    return permissions;
   269  }
